def second_to_last(head):
    if head is None or head.next is None:
        return None
    curr = head
    while curr.next is not None and curr.next.next is not None:
        curr = curr.next
    return curr

def traverse_generator(head):
    curr = head
    while curr is not None:
        yield curr.data
        curr = curr.next

def sum_first_k(head, k):
    gen = traverse_generator(head)
    total = 0
    for _ in range(k):
        try:
            total += next(gen)
        except StopIteration:
            break
    return total

