def filter_by_threshold(head, threshold):
    dummy = Node(0)
    dummy.next = head
    prev = dummy
    current = head
    while current is not None:
        if current.data > threshold:
            prev.next = current.next
        else:
            prev = current
        current = current.next
    return dummy.next
